package com.hbm.machine.solarboiler;
import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.neoforged.neoforge.client.model.data.*;
/** Actual saved target, sky-light subtraction and per-tick source heat; client one-tick delayed mirror queue. */
public final class SolarMirrorBlockEntity extends BlockEntity {
 public record Target(int dx,int dy,int dz,boolean raised){}public static final ModelProperty<Target> TARGET=new ModelProperty<>();public int tX,tY,tZ;public boolean isOn;
 public SolarMirrorBlockEntity(BlockPos pos,BlockState state){super(SolarBoilerContent.MIRROR_BE.get(),pos,state);}
 public static void tick(Level level,BlockPos pos,BlockState state,SolarMirrorBlockEntity mirror){if(level instanceof ServerLevel server)mirror.serverTick(server);else{if(mirror.isOn&&level.getBlockEntity(new BlockPos(mirror.tX,mirror.tY-1,mirror.tZ)) instanceof SolarBoilerBlockEntity boiler)boiler.primary.add(pos.immutable());if(level.getGameTime()%20==0)mirror.rebuild();}}
 private void serverTick(ServerLevel server){if(server.getGameTime()%20==0)send(server);if(tY<worldPosition.getY()){isOn=false;return;}int sun=server.getBrightness(LightLayer.SKY,worldPosition)-server.getSkyDarken()-11;if(sun<=0||!server.canSeeSky(worldPosition.above())){isOn=false;return;}isOn=true;if(server.getBlockEntity(new BlockPos(tX,tY-1,tZ)) instanceof SolarBoilerBlockEntity boiler)boiler.heat+=sun;}
 public void setTarget(int x,int y,int z){tX=x;tY=y;tZ=z;setChanged();if(level instanceof ServerLevel server)send(server);}
 private void send(ServerLevel server){var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<40000)player.connection.send(packet);dispatchScope.commit();}}
 public void rebuild(){requestModelDataUpdate();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
 @Override public ModelData getModelData(){return ModelData.builder().with(TARGET,new Target(tX-worldPosition.getX(),tY-worldPosition.getY(),tZ-worldPosition.getZ(),tY>worldPosition.getY())).build();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);tag.putInt("targetX",tX);tag.putInt("targetY",tY);tag.putInt("targetZ",tZ);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);tX=tag.getInt("targetX");tY=tag.getInt("targetY");tZ=tag.getInt("targetZ");}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();saveAdditional(tag,lookup);tag.putBoolean("isOn",isOn);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){loadAdditional(tag,lookup);isOn=tag.getBoolean("isOn");rebuild();}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
}
